def fmt(x):
    d=Decimal(str(x)).quantize(Decimal('0.001'),rounding=ROUND_HALF_UP)
    return format(d,'f').rstrip('0').rstrip('.') if '.' in format(d,'f') else str(d)

def question(subject, ident, topic, stem, choices, answer, explanation, **extra):
    return dict(id=ident, subject=SUBJECTS[subject], topic=topic, question=stem,
        choices=choices, answer=answer, explanation=explanation, difficulty='중',
        year=None,session=None,type='original',sourceUrl=SOURCE,verificationStatus='reviewed',
        reviewNote=NOTE,version='main',rights='자체 제작 · CC BY 4.0 · 저장소 및 변경 내용 표시. 외부 기출 복제 없음.',**extra)


def build_expansion():
    bank=[]
    for subject, text in CONCEPTS.items():
        lines=text.strip().splitlines()
        assert len(lines)==40,(subject,len(lines))
        for i,line in enumerate(lines):
            topic,stem,answer,*rest=line.split('|')
            options=[answer,*rest[:3]];shift=(i+subject)%4
            choices=options[shift:]+options[:shift]
            bank.append(question(subject,f'FPE-C{subject+1}-{i+1:03}',topic,stem,choices,choices.index(answer)+1,rest[3]))
    bank.extend(calculations())
    assert len(bank)==920
    return bank


def calculations():
    bank=[]
    # Each formula is a study model with assumptions and units in the stem.
    # n indexes distinct physical input combinations, never source year/session.
    for n in range(40):
        d=Decimal; t=n+1
        # Six fire-science families: 240 variants.
        add(bank,0,'sensible',n,'물의 감열',
            [2+t,d('4.2'),10+(n%8)*5], 'kJ',
            lambda m,c,dt:m*c*dt,
            lambda m,c,dt:f'질량 {fmt(m)} kg의 물을 {fmt(dt)} K만큼 가열한다. 비열은 {fmt(c)} kJ/(kg·K)로 일정하며 손실과 상태 변화는 없다. 흡수 열량은?',
            '감열량 Q=m c ΔT. 질량 kg × 비열 kJ/(kg·K) × 온도차 K를 곱하면 kJ이다.')
        add(bank,0,'latent',n,'기화잠열',
            [d(t)/10,2250], 'kJ',lambda m,h:m*h,
            lambda m,h:f'끓는 물 {fmt(m)} kg이 같은 온도에서 모두 증발한다. 기화잠열을 {fmt(h)} kJ/kg으로 가정하고 손실은 무시한다. 증발 과정의 흡수 열량은?',
            '상변화 열량 Q=m h. 이미 끓는 온도이므로 온도 상승에 필요한 감열을 추가하지 않는다.')
        add(bank,0,'hrr',n,'질량연소와 발열률',
            [d(t+2)/1000,20+(n%5)*5], 'kW',lambda mdot,h:mdot*h*1000,
            lambda mdot,h:f'완전연소하는 연료의 질량연소율은 {fmt(mdot)} kg/s, 유효 연소열은 {fmt(h)} MJ/kg이다. 연소열이 전부 열로 방출된다고 가정할 때 발열률은?',
            '발열률 Q̇=질량연소율 × 유효 연소열. MJ/s를 kW로 바꾸기 위해 1000을 곱한다.')
        add(bank,0,'conduction',n,'평판 전도',
            [d('0.2')+d(n)/100,2+(n%4),100+(n%8)*10,d('0.1')], 'W',lambda k,a,dt,l:k*a*dt/l,
            lambda k,a,dt,l:f'두께 {fmt(l)} m인 평판의 열전도율은 {fmt(k)} W/(m·K), 면적은 {fmt(a)} m², 양면 온도차는 {fmt(dt)} K이다. 정상 1차원 전도이며 접촉저항을 무시한다. 열전달률은?',
            '정상 전도 열전달률 Q̇=k A ΔT / L. 두께 m로 나누어 단위 W를 얻는다.')
        add(bank,0,'fireload',n,'가연물 잠재열량',
            [10+t,16+(n%5),10+(n%4)*5], 'MJ/m²',lambda m,h,a:m*h/a,
            lambda m,h,a:f'면적 {fmt(a)} m² 공간에 질량 {fmt(m)} kg의 가연물만 있다. 단위질량 연소열은 {fmt(h)} MJ/kg이다. 다른 가연물을 무시할 때 단위 바닥면적당 잠재 발열량은?',
            '면적당 잠재 발열량은 m H / A. 총 잠재열량 MJ를 바닥면적 m²로 나눈다. 실제 연소효율이나 법정 설계값을 뜻하지 않는다.')
        add(bank,0,'gaspressure',n,'정적 이상기체 압력',
            [100+(n%5)*10,300,330+t*3], 'kPa',lambda p,t1,t2:p*t2/t1,
            lambda p,t1,t2:f'밀폐된 강체 용기에 일정량의 이상기체가 있다. 초기 절대압력 {fmt(p)} kPa, 초기 절대온도 {fmt(t1)} K에서 {fmt(t2)} K로 가열한다. 부피 일정일 때 최종 절대압력은?',
            '일정 몰수·부피의 이상기체는 P/T가 일정하다. P₂=P₁ T₂/T₁에 절대압력과 절대온도를 사용한다.')
        # Seven electrical families: 280 variants.
        add(bank,1,'ohm',n,'직류 전류',
            [12+(n%5)*6,20+t*2], 'A',lambda v,r:v/r,
            lambda v,r:f'저항 {fmt(r)} Ω에 일정한 직류 {fmt(v)} V를 인가한다. 이상적인 저항이며 온도 변화는 무시한다. 흐르는 전류는?',
            '옴의 법칙 I=V/R. 전압 V를 저항 Ω으로 나누면 전류 A가 된다.')
        add(bank,1,'series',n,'직렬 합성저항',
            [10+t,20+(n%7)*3], 'Ω',lambda a,b:a+b,
            lambda a,b:f'저항 {fmt(a)} Ω과 {fmt(b)} Ω을 직렬 연결한다. 도선 저항을 무시할 때 합성저항은?',
            '직렬 저항은 같은 전류가 흐르므로 전압 강하를 합하면 R=R₁+R₂이다.')
        add(bank,1,'parallel',n,'병렬 합성저항',
            [20+t*2,40+(n%5)*10], 'Ω',lambda a,b:a*b/(a+b),
            lambda a,b:f'저항 {fmt(a)} Ω과 {fmt(b)} Ω을 병렬 연결한다. 접속 저항은 무시한다. 합성저항은?',
            '병렬 컨덕턴스 합 1/R=1/R₁+1/R₂에서 R=R₁R₂/(R₁+R₂)이다. 결과는 더 작은 가지 저항보다 작아야 한다.')
        add(bank,1,'dcPower',n,'직류 부하 전력',
            [12+(n%4)*12,d(t+2)/10], 'W',lambda v,i:v*i,
            lambda v,i:f'직류 부하 양단 전압이 {fmt(v)} V이고 전류가 {fmt(i)} A로 일정하다. 부하 소비전력은?',
            '직류 전력 P=V I. 전압 V와 전류 A의 곱으로 W를 구한다.')
        add(bank,1,'energy',n,'부하 전력량',
            [50+t*5,2+(n%6)], 'kWh',lambda p,t:p*t/1000,
            lambda p,t:f'소비전력 {fmt(p)} W인 부하를 일정하게 {fmt(t)} 시간 사용한다. 전력량은?',
            '전력량 E=P t. W를 kW로 변환하려면 1000으로 나누고 시간 h를 곱하여 kWh를 얻는다.')
        add(bank,1,'capacitorCharge',n,'축전기 전하',
            [10+t*5,12+(n%4)*6], 'mC',lambda c,v:c*v/1000,
            lambda c,v:f'정전용량 {fmt(c)} μF의 이상적인 축전기 양단에 {fmt(v)} V가 걸려 있다. 한쪽 전극에 저장된 전하량의 크기는?',
            'Q=C V. μF를 F로 바꿀 때 10⁻⁶을 곱하고 C를 mC로 바꿀 때 1000을 곱하므로 최종적으로 C(μF) V /1000이다.')
        add(bank,1,'transformer',n,'이상 변압기',
            [220,100+(n%5)*20,20+t], 'V',lambda v,n1,n2:v*n2/n1,
            lambda v,n1,n2:f'이상적인 변압기의 1차 전압은 {fmt(v)} V, 1차 권수는 {fmt(n1)} 회, 2차 권수는 {fmt(n2)} 회이다. 누설·손실을 무시할 때 2차 전압은?',
            '이상 변압기의 권수비 V₂/V₁=N₂/N₁. 따라서 V₂=V₁ N₂/N₁이다.')
        # Seven fire electrical engineering families: 280 variants.
        add(bank,3,'batteryDuty',n,'비상전원 전하량',
            [d('0.1')+d(n)/100,4+(n%4),d('0.8')+d(n%6)/10,d('0.5')], 'Ah',lambda a,t,b,s:a*t+b*s,
            lambda a,t,b,s:f'학습용 경보 설비가 감시 상태 {fmt(a)} A로 {fmt(t)} h, 이어 경보 상태 {fmt(b)} A로 {fmt(s)} h 동작한다. 두 상태는 겹치지 않으며 이상적인 축전지로 손실·여유율은 무시한다. 필요한 최소 전하 용량은?',
            '상태별 전하량을 더한다. C=I감시 t감시+I경보 t경보. A×h=Ah이며 이 시간 조건은 법정 비상전원 기준이 아닌 문제의 가정이다.')
        add(bank,3,'voltageDrop',n,'경보 배선 전압강하',
            [d('0.02'),10+t*2,d('0.1')+d(n%5)/10,d('1.5')], 'V',lambda rho,l,i,a:2*rho*l*i/a,
            lambda rho,l,i,a:f'직류 경보기로 가는 2선식 배선의 편도 길이는 {fmt(l)} m, 각 선 단면적은 {fmt(a)} mm²이다. 저항률은 {fmt(rho)} Ω·mm²/m, 부하 전류는 {fmt(i)} A이다. 양쪽 선 길이가 같고 접촉저항을 무시할 때 왕복 배선 전압강하는?',
            '왕복 길이는 2L이다. R선로=2ρL/A, ΔV=I R선로. 편도 길이를 그대로 쓰는 오류를 피한다.')
        add(bank,3,'alarmLoads',n,'병렬 경보기 소비전류',
            [2+t,d('0.02')+d(n%5)/100,d('0.1')], 'A',lambda count,i,base:count*i+base,
            lambda count,i,base:f'경보 시 각각 {fmt(i)} A를 소비하는 동일 경보기 {fmt(count)} 개가 병렬 연결된다. 제어반의 경보 시 전류는 별도로 {fmt(base)} A이다. 다른 부하가 없을 때 전원 전체 경보 전류는?',
            '병렬 경보기 전류의 합과 제어반 전류를 더한다. I전체=N I기기+I제어반이며 전압을 더하지 않는다.')
        add(bank,3,'eolCurrent',n,'종단 감시회로 전류',
            [24,1000+t*50,20+(n%5)*10], 'mA',lambda v,r,line:1000*v/(r+line),
            lambda v,r,line:f'학습용 감시회로의 직류 전원이 {fmt(v)} V이다. 종단저항 {fmt(r)} Ω과 왕복 선로저항 {fmt(line)} Ω만 직렬 연결되어 있고 감지기 전류는 무시한다. 정상 감시 전류는?',
            '직렬 합성저항은 R종단+R선로이다. I=V/(R종단+R선로) A를 구한 뒤 1000을 곱해 mA로 바꾼다. 실제 수신기 회로의 법정 사양을 뜻하지 않는다.')
        add(bank,3,'speakerLoad',n,'정전압 방송 전력 합',
            [3+t,1+(n%4),5+(n%5),3], 'W',lambda n1,p1,n2,p2:n1*p1+n2*p2,
            lambda n1,p1,n2,p2:f'정전압 방송 선로에 {fmt(p1)} W 탭 스피커 {fmt(n1)} 개와 {fmt(p2)} W 탭 스피커 {fmt(n2)} 개를 연결한다. 각 탭의 정격 전압으로 공급하고 손실과 여유율을 무시한다. 스피커 정격 부하 합계는?',
            '각 그룹의 탭 전력과 개수를 곱해 더한다. P합=N₁P₁+N₂P₂이다. 앰프의 실제 선정은 별도 여유와 손실·설계 조건을 확인해야 한다.')
        add(bank,3,'terminalVoltage',n,'말단 공급전압',
            [24,d('0.1')+d(t)/100,2+(n%4)], 'V',lambda v,i,r:v-i*r,
            lambda v,i,r:f'직류 {fmt(v)} V 전원에서 말단 장치로 {fmt(i)} A가 흐른다. 왕복 배선 전체 저항은 {fmt(r)} Ω이고 접촉저항은 무시한다. 말단 장치 양단 전압은?',
            '선로 전압강하는 I R이고 말단 전압 V말단=V전원-I R이다. 이미 왕복 전체 저항을 주었으므로 길이 보정으로 다시 2배하지 않는다.')
        add(bank,3,'batteryUsable',n,'축전지 유효 용량',
            [2+t,d('0.8'),d('0.2')+d(n%5)/10], 'h',lambda c,k,i:c*k/i,
            lambda c,k,i:f'경보장치 축전지의 공칭 용량은 {fmt(c)} Ah이고 문제에서 사용 가능한 비율을 {fmt(k)}로 정한다. 부하가 일정한 {fmt(i)} A일 때 단순 전하량 모델의 최대 공급 시간은? 온도·방전율·전압 변화를 무시한다.',
            '유효 전하량=C공칭×사용가능비율이다. 일정 전류 공급 시간 t=C유효/I이다. 실제 축전지 성능 곡선이나 법정 유지시간을 대신하는 모델이 아니다.')
    return bank


def add(bank,subject,kind,n,topic,values,unit,evaluate,stem,reason):
    v=[Decimal(str(x)) for x in values]
    raw=evaluate(*v)
    answer=raw.quantize(Decimal('0.001'),rounding=ROUND_HALF_UP)
    assert answer>0
    # Plausible numerical alternatives, rounded separately; never equivalent units.
    alternatives=[answer,(raw*Decimal('0.8')).quantize(Decimal('0.001'),rounding=ROUND_HALF_UP),
        (raw*Decimal('1.2')).quantize(Decimal('0.001'),rounding=ROUND_HALF_UP),
        (raw*Decimal('1.5')).quantize(Decimal('0.001'),rounding=ROUND_HALF_UP)]
    assert len(set(alternatives))==4
    shift=(n+subject)%4;options=alternatives[shift:]+alternatives[:shift]
    explanation=reason
    # Explicit input -> numerical substitution -> result is stored for every variant.
    equations={
      'sensible':lambda: f'{fmt(v[0])} × {fmt(v[1])} × {fmt(v[2])}',
      'latent':lambda: f'{fmt(v[0])} × {fmt(v[1])}',
      'hrr':lambda: f'{fmt(v[0])} × {fmt(v[1])} × 1000',
      'conduction':lambda: f'{fmt(v[0])} × {fmt(v[1])} × {fmt(v[2])} ÷ {fmt(v[3])}',
      'fireload':lambda: f'{fmt(v[0])} × {fmt(v[1])} ÷ {fmt(v[2])}',
      'gaspressure':lambda: f'{fmt(v[0])} × {fmt(v[2])} ÷ {fmt(v[1])}',
      'ohm':lambda: f'{fmt(v[0])} ÷ {fmt(v[1])}',
      'series':lambda: f'{fmt(v[0])} + {fmt(v[1])}',
      'parallel':lambda: f'({fmt(v[0])} × {fmt(v[1])}) ÷ ({fmt(v[0])} + {fmt(v[1])})',
      'dcPower':lambda: f'{fmt(v[0])} × {fmt(v[1])}',
      'energy':lambda: f'{fmt(v[0])} × {fmt(v[1])} ÷ 1000',
      'capacitorCharge':lambda: f'{fmt(v[0])} × {fmt(v[1])} ÷ 1000',
      'transformer':lambda: f'{fmt(v[0])} × {fmt(v[2])} ÷ {fmt(v[1])}',
      'batteryDuty':lambda: f'{fmt(v[0])} × {fmt(v[1])} + {fmt(v[2])} × {fmt(v[3])}',
      'voltageDrop':lambda: f'2 × {fmt(v[0])} × {fmt(v[1])} × {fmt(v[2])} ÷ {fmt(v[3])}',
      'alarmLoads':lambda: f'{fmt(v[0])} × {fmt(v[1])} + {fmt(v[2])}',
      'eolCurrent':lambda: f'1000 × {fmt(v[0])} ÷ ({fmt(v[1])} + {fmt(v[2])})',
      'speakerLoad':lambda: f'{fmt(v[0])} × {fmt(v[1])} + {fmt(v[2])} × {fmt(v[3])}',
      'terminalVoltage':lambda: f'{fmt(v[0])} - {fmt(v[1])} × {fmt(v[2])}',
      'batteryUsable':lambda: f'{fmt(v[0])} × {fmt(v[1])} ÷ {fmt(v[2])}',
    }
    explanation+=f' 주어진 조건을 대입하면 {equations[kind]()} = {fmt(answer)} {unit}이다. 반올림 전 값으로 계산한 후 최종 결과를 소수 셋째 자리까지 사사오입한다(불필요한 끝자리 0은 생략).'
    q=question(subject,f'FPE-N-{kind}-{n+1:03}',topic,
        stem(*v)+' 결과는 소수 셋째 자리까지 반올림하고 끝자리 0은 생략한다.',
        [f'{fmt(x)} {unit}' for x in options],options.index(answer)+1,explanation,
        family=f'FPE-{kind}',calculation=dict(kind=kind,values=[float(x) for x in v],result=float(answer),unit=unit,precision=3))
    q['reviewNote']=NOTE+' 수치 조건 변형 family. Python Decimal 생성과 별도 TypeScript 계산 경로로 수치·정답번호·보기 유일성 검증. 전 범위 전문가 검수를 뜻하지 않음.'
    bank.append(q)
